"""Add audit-only interactive panels to a verified SWELL public replay; no external requests."""
import json, zipfile, argparse, math, hashlib
from pathlib import Path
from radar_investigation import footprint, within, investigation
from build_public_replay import verify, build

def enhance(package,html,output,momentum=None):
    manifest,r,e,v=verify(package)
    with zipfile.ZipFile(package) as z:
        if 'assurance/radar-audit.json' not in z.namelist():raise ValueError('Export the matching radar assurance archive first')
        a=json.loads(z.read('assurance/radar-audit.json'))
    if a['site_hash']!=e['hash'] or a['geometry']['n']!=e['total_cells']**.5:raise ValueError('Radar audit mismatch')
    c=v['radar_selection'];g=a['geometry'];f=footprint(g,c['row'],c['col']); lat,lon=g['lat'][c['row']][c['col']],g['lon'][c['row']][c['col']];loc=v['local_location'];linked=within(f,loc['lat'],loc['lon'])
    new={'study_hash':e['hash'],'geometry':g,'latest':a['latest_pair'],'pairs':[{'pair':x['pair'],'strict':x['threshold_0_5_valid_blocks'],'component':x['valid_component_referenced_blocks']} for x in a['granules']],'selection':{'row':c['row'],'col':c['col'],'audited_lat':lat,'audited_lon':lon,'terrain':loc,'center_inside':linked,'footprint':f},'investigation':investigation(a,c,e),'limitations':a['limitations'],'closure':a['phase_closure']}
    if momentum:
        m=json.loads(Path(momentum).read_text());
        if m['run_id']!=r['run_id'] or m['archive_sha256']!=hashlib.sha256(Path(package).read_bytes()).hexdigest():raise ValueError('Momentum experiment mismatch')
        new['momentum']=m
    raw=Path(html).read_text(encoding='utf-8');start=raw.index('const d=')+8;old,_=json.JSONDecoder().raw_decode(raw[start:].lstrip())
    if old['run_id']!=r['run_id']:raise ValueError('Replay run mismatch')
    data=json.dumps(new,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    panel='''<section class="card" id="assurance"><div class="tag">SCIENTIFIC INVESTIGATION / SOURCE AUDIT</div><h2>What does the radar really tell us?</h2><p id="geoFinding" class="warning"></p><div class="grid"><div><h3>Latest pair · audited raw phase</h3><label>Block mean common-support coherence screen <select id="auditThreshold"><option value="0.3">0.30</option><option value="0.5" selected>0.50</option><option value="0.7">0.70</option></select></label><canvas id="auditMap" width="420" height="420" aria-label="Audited raw phase, select block"></canvas><p id="auditSelection"></p><p class="muted">Color: signed radians, not displacement. This interactive threshold filters block mean coherence; stricter native pixel audit counts are shown separately.</p></div><div><h3>Native-pixel + connected-component audit</h3><div id="pairBars"></div><p class="muted" id="auditLimits"></p><h3>Competing explanations for the original saved observation</h3><div id="auditHypotheses"></div></div></div><details><summary>Original selected block footprint and coordinates</summary><pre id="coordDetails" style="white-space:pre-wrap"></pre></details><div id="momentumPanel" hidden><h2>Alternative solver: same archived terrain</h2><p id="momentumStatus" class="warning"></p><div class="scroll"><table><thead><tr><th>Max step</th><th>Baseline peak m</th><th>Wet area m²</th><th>Storage reduction m³</th></tr></thead><tbody id="momentumRows"></tbody></table></div><h3>Equal-footprint alternatives at 1 s cap</h3><div id="optionRows"></div></div></section>'''
    # Put the review before the legacy hydraulic comparison so the geographic discrepancy cannot be missed.
    raw=raw.replace('<section class="card"><div class="tag">02 / COMPARE</div>',panel+'<section class="card"><div class="tag">02 / COMPARE</div>',1)
    js='''<script>const A=__DATA__;(function(){const $=id=>document.getElementById(id),s=A.selection,g=A.geometry,n=g.n,p=A.latest;const fmt=(v,k=2)=>Number.isFinite(v)?v.toFixed(k):'withheld';const el=(tag,text,par)=>{let x=document.createElement(tag);x.textContent=text;par.append(x);return x};$('geoFinding').textContent=s.center_inside?'Saved terrain center is inside the recovered radar block. This is geographic linkage, not causality.':'IMPORTANT: the saved terrain center is outside the recovered radar block. The water experiment below is a separate model experiment, not a local explanation of this radar observation.';$('coordDetails').textContent=JSON.stringify(s,null,2);$('auditLimits').textContent=A.limitations+' '+A.closure;for(const q of A.pairs){let row=el('div',q.pair.join(' → ')+' · '+q.strict+'/'+n*n,$('pairBars'));let bar=el('div','',row);bar.style.cssText='height:7px;background:#193542;margin:3px 0 9px;border-radius:3px';let fill=el('div','',bar);fill.style.cssText='height:100%;background:#5ee0ce;border-radius:3px;width:'+(100*q.strict/n/n)+'%'}for(const h of A.investigation.hypotheses){let d=el('details','',$('auditHypotheses'));el('summary',h.name+' — '+h.status,d);el('p',h.evidence,d);el('p','Next test: '+h.next,d)}let rr=s.row,cc=s.col;function render(){const q=Number($('auditThreshold').value),vals=p.component_referenced_raw_phase_rad;const valid=(i,j)=>Number.isFinite(vals[i][j])&&Number.isFinite(p.common_support_coherence[i][j])&&p.common_support_coherence[i][j]>=q;const max=Math.max(.001,...vals.flat().filter(Number.isFinite).map(Math.abs));let ctx=$('auditMap').getContext('2d'),w=420/n,ct=0;for(let i=0;i<n;i++)for(let j=0;j<n;j++){let v=vals[i][j];if(valid(i,j)){ct++;let x=Math.abs(v)/max;ctx.fillStyle=v>=0?`rgb(${150+105*x},${160-62*x},${155-85*x})`:`rgb(${150-100*x},${160+70*x},${155+80*x})`;}else ctx.fillStyle='#35424c';ctx.fillRect(j*w,i*w,w+.3,w+.3)}ctx.strokeStyle='white';ctx.lineWidth=2;ctx.strokeRect(cc*w,rr*w,w,w);$('auditSelection').textContent=`${ct}/${n*n} shown · shared ±${fmt(max,2)} rad · cell ${rr}, ${cc} · ${valid(rr,cc)?fmt(vals[rr][cc])+' rad':'withheld'} · q ${fmt(p.common_support_coherence[rr][cc],3)} · common native support ${fmt(100*p.valid_support_fraction[rr][cc],1)}% · ${fmt(g.lat[rr][cc],6)}, ${fmt(g.lon[rr][cc],6)} · ${g.analysis_spacing_m.join(' × ')} m block`}$('auditThreshold').onchange=render;$('auditMap').onclick=e=>{let b=e.target.getBoundingClientRect();cc=Math.min(n-1,Math.max(0,Math.floor((e.clientX-b.left)/b.width*n)));rr=Math.min(n-1,Math.max(0,Math.floor((e.clientY-b.top)/b.height*n)));render()};render();if(A.momentum){let m=A.momentum;$('momentumPanel').hidden=false;$('momentumStatus').textContent=(m.screen_passed?'Preset maximum-timestep screen passed in both alternatives. ':'Preset screen not met. ')+m.warning;for(let c of m.cases){let row=el('tr','',$('momentumRows'));for(let v of [c.max_dt_s+' s',fmt(c.peak_m,6),c.wet_m2,fmt(c.storage_reduction_m3)])el('td',v,row)}for(let c of m.alternatives)el('p',c.name+' · '+fmt(c.storage_reduction_m3)+' m³ less storage · '+c.reduced_gt_1cm_m2+' m² peak reduction >1 cm. Not cost-equivalent or optimized.',$('optionRows'))}})();</script>'''.replace('__DATA__',data)
    raw=raw.replace('</body>',js+'</body>');Path(output).write_text(raw,encoding='utf-8');return new

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--package',required=True);p.add_argument('--replay');p.add_argument('--momentum');p.add_argument('--output',default='competition-replay.html');args=p.parse_args();tmp=Path(args.output).with_suffix('.base.html');source=args.replay or build(args.package,tmp);enhance(args.package,source,args.output,args.momentum);print('Saved',args.output)
